def test_roundtrip_json_wordinvariants():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "allRelationshipIdsResolve": true,
      "allContentTypesDeclared": true,
      "noDuplicateRelationshipIds": true,
      "allMediaPartsReachable": true,
      "noOrphanRequiredParts": true,
      "allHyperlinksHaveRelationships": true,
      "allAnchorLinksHaveBookmarks": true,
      "allNumberingReferencesDefined": true,
      "allTableHeadersMarked": true
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = WordInvariants.load(original_data)
    saved_data = instance.save()
    reloaded = WordInvariants.load(saved_data)
    assert reloaded is not None
    assert reloaded.all_relationship_ids_resolve
    assert reloaded.all_content_types_declared
    assert reloaded.no_duplicate_relationship_ids
    assert reloaded.all_media_parts_reachable
    assert reloaded.no_orphan_required_parts
    assert reloaded.all_hyperlinks_have_relationships
    assert reloaded.all_anchor_links_have_bookmarks
    assert reloaded.all_numbering_references_defined
    assert reloaded.all_table_headers_marked


